using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Host;
using MiniFramework.Providers.Fake;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;

namespace MiniFramework.ResourceScheduler.Tests
{
    public sealed class ResourceSchedulerTests
    {
        private static CleanupContext Cleanup=>new CleanupContext(CancellationToken.None,Timeout.InfiniteTimeSpan);
        private static FrameworkError Failed=>new FrameworkError(ErrorKind.Provider,"test.failed");
        private static ResourceKey Key(string address="a")=>new ResourceKey("fake","main","v1",address,typeof(string));
        private static ResourceScheduleBudget Budget(int downloads=1,int loads=1,int units=2,int capacity=128,int starts=64)=>new ResourceScheduleBudget(downloads,loads,units,TimeSpan.FromMilliseconds(5),capacity,starts);
        private sealed class Clock:IMonotonicClock {public double Now;public double Seconds=>Now;}
        private sealed class Op<T>:IProviderOperation<T>
        {
            private readonly UniTaskCompletionSource<Result<T>> source=new UniTaskCompletionSource<Result<T>>();
            public string Id=>"test";public BackendState State{get;private set;}=BackendState.Running;public UniTask<Result<T>> Completion=>source.Task;
            public void Complete(Result<T> result){State=result.IsSuccess?BackendState.Succeeded:BackendState.Failed;source.TrySetResult(result);}
        }
        private static Result<IProviderOperation<Unit>> Start(Op<Unit> operation)=>Result<IProviderOperation<Unit>>.Success(operation);
        private static Result<IProviderOperation<Unit>> Instant(){var op=new Op<Unit>();op.Complete(Result<Unit>.Success(default));return Start(op);}
        private sealed class Staged:IAssetProvider,IAssetDownloadProvider
        {
            public readonly FakeResourceProvider Inner=new FakeResourceProvider();public readonly List<Op<Unit>> Downloads=new List<Op<Unit>>();
            public string Id=>Inner.Id;
            public Result<IProviderOperation<Unit>> BeginDownload(ResourceKey key){var op=new Op<Unit>();Downloads.Add(op);return Start(op);}
            public Result<IProviderOperation<IProviderAsset<T>>> BeginLoad<T>(ResourceKey key)where T:class=>Inner.BeginLoad<T>(key);
            public Result<IProviderOperation<IProviderAsset<T>>> BeginLoadPrepared<T>(ResourceKey key)where T:class=>Inner.BeginLoad<T>(key);
        }
        private sealed class Env
        {
            public readonly ResourceWorkScheduler Scheduler=new ResourceWorkScheduler(Budget());
            public readonly FakeResourceProvider Provider;public readonly Staged Staged;public AssetsService Assets;public GameContext Context;
            public Env(bool staged=false){if(staged){Staged=new Staged();Provider=Staged.Inner;}else Provider=new FakeResourceProvider();}
            public async UniTask Init(){Assets=new AssetsService((IAssetProvider)Staged??Provider,"main","v1",Cleanup,scheduler:Scheduler,schedulerModuleId:Scheduler.Id);Context=new GameContext(new[]{new ModuleRegistration(Scheduler.Id,Scheduler.Dependencies,()=>Scheduler,typeof(IResourceWorkScheduler)),new ModuleRegistration(Assets.Id,Assets.Dependencies,()=>Assets,typeof(IAssetsService))},Cleanup);Assert.IsTrue((await Context.StartAsync(OperationContext.Unlimited())).IsSuccess);}
            public void Release(int i=0)=>Provider.AssetAt<string>(i).Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));
            public async UniTask CloseOwner(Scope owner){var close=owner.CloseAsync(Cleanup);while(close.Status==UniTaskStatus.Pending){for(var i=0;i<Provider.AssetStartCount;i++)Provider.AssetAt<string>(i).Asset?.ReleaseAttempt?.Complete(Result<Unit>.Success(default));await UniTask.Yield();}Assert.IsTrue((await close).IsFullyDrained);}
            public async UniTask Finish(){Assert.IsTrue((await Context.CloseAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(0,Assets.RetainedEntryCount);Assert.AreEqual(0,Scheduler.ActiveDownloads+Scheduler.ActiveLoads+Scheduler.QueuedDownloads+Scheduler.QueuedLoads);}
        }
        [Test] public void InvalidBudgetsReject(){Assert.Throws<ArgumentOutOfRangeException>(()=>Budget(loads:0));Assert.Throws<ArgumentOutOfRangeException>(()=>Budget(capacity:0));Assert.Throws<ArgumentOutOfRangeException>(()=>new ResourceScheduleBudget(1,1,1,TimeSpan.Zero));}
        [UnityTest] public IEnumerator EnqueueIsColdUntilTick()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());var n=0;var job=s.Schedule(ResourceLane.Load,()=>{n++;return Instant();}).Value;Assert.AreEqual(0,n);Assert.AreEqual(ResourceWorkState.Queued,job.SchedulingState);s.Tick();Assert.IsTrue((await job.Completion).IsSuccess);Assert.AreEqual(1,n);Assert.AreEqual(0,s.ActiveLoads);});
        [Test] public void IndependentDownloadAndLoadLimits(){var s=new ResourceWorkScheduler(Budget(downloads:2));var ops=new List<Op<Unit>>();for(var i=0;i<3;i++){var d=new Op<Unit>();var l=new Op<Unit>();ops.Add(d);ops.Add(l);s.Schedule(ResourceLane.Download,()=>Start(d));s.Schedule(ResourceLane.Load,()=>Start(l));}s.Tick();Assert.AreEqual(2,s.ActiveDownloads);Assert.AreEqual(1,s.ActiveLoads);Assert.AreEqual(1,s.QueuedDownloads);Assert.AreEqual(2,s.QueuedLoads);foreach(var op in ops)op.Complete(Result<Unit>.Success(default));s.Tick();Assert.AreEqual(0,s.ActiveLoads+s.ActiveDownloads);}
        [Test] public void PriorityThenStableFifo(){var s=new ResourceWorkScheduler(Budget());var order="";s.Schedule(ResourceLane.Load,()=>{order+="a";return Instant();},ResourcePriority.Normal);s.Schedule(ResourceLane.Load,()=>{order+="b";return Instant();},ResourcePriority.Critical);s.Schedule(ResourceLane.Load,()=>{order+="c";return Instant();},ResourcePriority.Critical);s.Schedule(ResourceLane.Load,()=>{order+="d";return Instant();},ResourcePriority.Prefetch);s.Tick();Assert.AreEqual("bcad",order);}
        [Test] public void PromotionIsMonotonicAndNotPreemption(){var s=new ResourceWorkScheduler(Budget());var order="";var a=s.Schedule(ResourceLane.Load,()=>{order+="a";return Instant();},ResourcePriority.Prefetch).Value;s.Schedule(ResourceLane.Load,()=>{order+="b";return Instant();});Assert.IsTrue(a.Promote(ResourcePriority.Critical));a.Promote(ResourcePriority.Prefetch);s.Tick();Assert.AreEqual("ab",order);Assert.IsFalse(a.Promote(ResourcePriority.Critical));}
        [UnityTest] public IEnumerator QueuedCancelNeverStartsAndIsIdempotent()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());var n=0;var job=s.Schedule(ResourceLane.Load,()=>{n++;return Instant();}).Value;Assert.IsTrue(job.CancelQueued());Assert.IsFalse(job.CancelQueued());s.Tick();Assert.AreEqual(ErrorKind.Canceled,(await job.Completion).Error.Kind);Assert.AreEqual(0,n);});
        [Test] public void DemandPrunedEvenWithOccupiedSlot(){var s=new ResourceWorkScheduler(Budget());var active=new Op<Unit>();s.Schedule(ResourceLane.Load,()=>Start(active));s.Tick();var wanted=true;var job=s.Schedule(ResourceLane.Load,Instant,stillWanted:()=>wanted).Value;wanted=false;s.Tick();Assert.AreEqual(ResourceWorkState.Completed,job.SchedulingState);Assert.AreEqual(0,s.QueuedLoads);Assert.AreEqual(1,s.ActiveLoads);active.Complete(Result<Unit>.Success(default));}
        [Test] public void RunningCannotCancelOrFreeQuotaEarly(){var s=new ResourceWorkScheduler(Budget());var op=new Op<Unit>();var running=s.Schedule(ResourceLane.Load,()=>Start(op)).Value;s.Tick();Assert.IsFalse(running.CancelQueued());var starts=0;s.Schedule(ResourceLane.Load,()=>{starts++;return Instant();});s.Tick();Assert.AreEqual(0,starts);op.Complete(Result<Unit>.Success(default));Assert.AreEqual(0,s.ActiveLoads);s.Tick();Assert.AreEqual(1,starts);}
        [UnityTest] public IEnumerator BackendFailureFreesOnlyItsOwnSlot()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());var op=new Op<Unit>();var a=s.Schedule(ResourceLane.Load,()=>Start(op)).Value;s.Tick();var b=s.Schedule(ResourceLane.Load,Instant).Value;op.Complete(Result<Unit>.Failure(Failed));Assert.IsFalse((await a.Completion).IsSuccess);s.Tick();Assert.IsTrue((await b.Completion).IsSuccess);Assert.AreEqual(0,s.ActiveLoads);});
        [UnityTest] public IEnumerator ThrowNullAndDefaultFailuresDoNotJamQueue()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());var a=s.Schedule<Unit>(ResourceLane.Load,()=>throw new Exception("start")).Value;var b=s.Schedule<Unit>(ResourceLane.Load,()=>Result<IProviderOperation<Unit>>.Success(null)).Value;var c=s.Schedule<Unit>(ResourceLane.Load,()=>default).Value;var d=s.Schedule(ResourceLane.Load,Instant).Value;s.Tick();Assert.AreEqual(ErrorKind.Provider,(await a.Completion).Error.Kind);Assert.AreEqual(ErrorKind.Integrity,(await b.Completion).Error.Kind);Assert.AreEqual(ErrorKind.InvalidResult,(await c.Completion).Error.Kind);Assert.IsTrue((await d.Completion).IsSuccess);Assert.AreEqual(0,s.ActiveLoads);});
        [UnityTest] public IEnumerator ThrowingDemandFailsWithoutConsumingSlot()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());var a=s.Schedule(ResourceLane.Load,Instant,stillWanted:()=>throw new Exception("predicate")).Value;s.Tick();Assert.AreEqual(ErrorKind.Unexpected,(await a.Completion).Error.Kind);Assert.AreEqual(0,s.ActiveLoads+s.QueuedLoads);});
        [UnityTest] public IEnumerator ReentrantCancellationContinuationCannotAdmitUnwantedWork()=>UniTask.ToCoroutine(async()=>
        {
            var s=new ResourceWorkScheduler(Budget());var starts=0;
            async UniTask Chain(){for(var i=0;i<3;i++){var op=s.Schedule(ResourceLane.Load,()=>{starts++;return Instant();},stillWanted:()=>false).Value;await op.Completion;}}
            var observer=Chain().Preserve();s.Tick();await observer;Assert.AreEqual(0,starts,"Admission must recheck newly enqueued demand.");
        });
        [Test] public void SynchronousStartsHavePerTickCap(){var s=new ResourceWorkScheduler(Budget(starts:2));for(var i=0;i<5;i++)s.Schedule(ResourceLane.Load,Instant);s.Tick();Assert.AreEqual(3,s.QueuedLoads);s.Tick();Assert.AreEqual(1,s.QueuedLoads);s.Tick();Assert.AreEqual(0,s.QueuedLoads);}
        [UnityTest] public IEnumerator CloseCancelsQueueButWaitsActualCompletion()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());var op=new Op<Unit>();s.Schedule(ResourceLane.Load,()=>Start(op));s.Tick();var queued=s.Schedule(ResourceLane.Load,Instant).Value;var close=s.CleanupAsync(Cleanup);Assert.AreEqual(UniTaskStatus.Pending,close.Status);Assert.AreEqual(ErrorKind.Canceled,(await queued.Completion).Error.Kind);op.Complete(Result<Unit>.Success(default));Assert.IsTrue((await close).IsSuccess);});
        [Test] public void ReentrantTickDoesNotBypassStartBudget(){var s=new ResourceWorkScheduler(Budget(starts:1));var n=0;s.Schedule(ResourceLane.Load,()=>{s.Tick();n++;return Instant();});s.Schedule(ResourceLane.Load,()=>{n++;return Instant();});s.Tick();Assert.AreEqual(1,n);s.Tick();Assert.AreEqual(2,n);}
        [Test] public void QueueCapacityRecoversAfterWithdrawal(){var s=new ResourceWorkScheduler(Budget(capacity:1));var a=s.Schedule(ResourceLane.Load,Instant).Value;Assert.AreEqual(ErrorKind.Unavailable,s.Schedule(ResourceLane.Load,Instant).Error.Kind);a.CancelQueued();Assert.IsTrue(s.Schedule(ResourceLane.Load,Instant).IsSuccess);s.Tick();}
        [Test] public void FrameUnitCountIsIndependentBudget(){var clock=new Clock();var s=new ResourceWorkScheduler(Budget(units:2),clock:clock);var n=0;for(var i=0;i<5;i++)s.ScheduleFrame(()=>{n++;return Result<Unit>.Success(default);});s.Tick();Assert.AreEqual(2,n);Assert.AreEqual(3,s.QueuedFrameUnits);s.Tick();Assert.AreEqual(4,n);s.Tick();Assert.AreEqual(5,n);}
        [Test] public void FrameTimeStopsBetweenNonPreemptibleUnits(){var clock=new Clock();var s=new ResourceWorkScheduler(Budget(units:5),clock:clock);var n=0;for(var i=0;i<3;i++)s.ScheduleFrame(()=>{n++;clock.Now+=.008;return Result<Unit>.Success(default);});s.Tick();Assert.AreEqual(1,n);Assert.AreEqual(1,s.FrameBudgetOverruns);Assert.AreEqual(2,s.QueuedFrameUnits);s.Tick();s.Tick();Assert.AreEqual(3,n);}
        [UnityTest] public IEnumerator FrameFailureAndClosedOwnerDoNotBlockFollowingUnit()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget(units:5));var scope=new Scope("frame");var never=s.ScheduleFrame<Unit>(()=>throw new Exception("must not run"),stillWanted:()=>scope.State==ScopeState.Open).Value;await scope.CloseAsync(Cleanup);var fail=s.ScheduleFrame<Unit>(()=>throw new Exception("work")).Value;var pass=s.ScheduleFrame(()=>Result<Unit>.Success(default)).Value;s.Tick();Assert.AreEqual(ErrorKind.Canceled,(await never.Completion).Error.Kind);Assert.IsFalse((await fail.Completion).IsSuccess);Assert.IsTrue((await pass.Completion).IsSuccess);});
        [Test] public void FrameRunsWhileNetworkAndLoadAreOccupied(){var s=new ResourceWorkScheduler(Budget());var d=new Op<Unit>();var l=new Op<Unit>();s.Schedule(ResourceLane.Download,()=>Start(d));s.Schedule(ResourceLane.Load,()=>Start(l));var n=0;s.ScheduleFrame(()=>{n++;return Result<Unit>.Success(default);});s.Tick();Assert.AreEqual(1,n);Assert.AreEqual(1,s.ActiveDownloads);Assert.AreEqual(1,s.ActiveLoads);d.Complete(Result<Unit>.Success(default));l.Complete(Result<Unit>.Success(default));}
        [Test] public void ReentrantFrameTickCannotResetBudget(){var s=new ResourceWorkScheduler(Budget(units:1));var n=0;s.ScheduleFrame(()=>{n++;s.Tick();return Result<Unit>.Success(default);});s.ScheduleFrame(()=>{n++;return Result<Unit>.Success(default);});s.Tick();Assert.AreEqual(1,n);s.Tick();Assert.AreEqual(2,n);}
        [UnityTest] public IEnumerator StopRejectsAllNewLanes()=>UniTask.ToCoroutine(async()=>{var s=new ResourceWorkScheduler(Budget());await s.CleanupAsync(Cleanup);Assert.AreEqual(ErrorKind.NotReady,s.Schedule(ResourceLane.Load,Instant).Error.Kind);Assert.AreEqual(ErrorKind.NotReady,s.ScheduleFrame(()=>Result<Unit>.Success(default)).Error.Kind);});
        [UnityTest] public IEnumerator TwentySharedWaitersHaveOneQueuedLoadAndSingleCancelIsIndependent()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();var owner=new Scope("many");var cts=new CancellationTokenSource();var canceled=e.Assets.Load<string>(Key(),owner).Value.WaitAsync(OperationContext.Unlimited(cts.Token));var waits=new List<UniTask<Result<IAssetLease<string>>>>();for(var i=0;i<19;i++)waits.Add(e.Assets.Load<string>(Key(),owner).Value.WaitAsync(OperationContext.Unlimited()));Assert.AreEqual(1,e.Scheduler.QueuedLoads);Assert.AreEqual(0,e.Assets.ActualLoadingCount);cts.Cancel();e.Scheduler.Tick();Assert.AreEqual(ErrorKind.Canceled,(await canceled).Error.Kind);Assert.AreEqual(1,e.Provider.AssetStartCount);e.Provider.AssetAt<string>(0).Succeed("value");foreach(var w in waits)Assert.IsTrue((await w).IsSuccess);var close=owner.CloseAsync(Cleanup);e.Release();await close;cts.Dispose();await e.Finish();});
        [UnityTest] public IEnumerator AllQueuedOwnersCloseWithoutStartingBackend()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();var owner=new Scope("queued");var wait=e.Assets.Load<string>(Key(),owner).Value.WaitAsync(OperationContext.Unlimited());Assert.IsTrue((await owner.CloseAsync(Cleanup)).IsFullyDrained);e.Scheduler.Tick();Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);Assert.AreEqual(0,e.Provider.AssetStartCount);await e.Finish();});
        [UnityTest] public IEnumerator CanceledRunningLoadKeepsSlotUntilLateActualResult()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();var a=new Scope("a");var wa=e.Assets.Load<string>(Key(),a).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();var ca=a.CloseAsync(Cleanup);await wa;var b=new Scope("b");var wb=e.Assets.Load<string>(Key("b"),b).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();Assert.AreEqual(1,e.Provider.AssetStartCount);Assert.AreEqual(1,e.Scheduler.ActiveLoads);e.Provider.AssetAt<string>(0).Succeed("late");Assert.AreEqual(0,e.Scheduler.ActiveLoads);Assert.AreEqual(UniTaskStatus.Pending,ca.Status);e.Scheduler.Tick();Assert.AreEqual(2,e.Provider.AssetStartCount);e.Release(0);await ca;e.Provider.AssetAt<string>(1).Succeed("b");await wb;var cb=b.CloseAsync(Cleanup);e.Release(1);await cb;await e.Finish();});
        [UnityTest] public IEnumerator DownloadAndLoadStagesUseIndependentSlots()=>UniTask.ToCoroutine(async()=>{var e=new Env(true);await e.Init();var owner=new Scope("stages");var a=e.Assets.Load<string>(Key(),owner).Value.WaitAsync(OperationContext.Unlimited());var b=e.Assets.Load<string>(Key("b"),owner).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();Assert.AreEqual(1,e.Staged.Downloads.Count);Assert.AreEqual(1,e.Assets.ActualDownloadingCount);Assert.AreEqual(0,e.Assets.ActualLoadingCount);e.Staged.Downloads[0].Complete(Result<Unit>.Success(default));e.Scheduler.Tick();Assert.AreEqual(2,e.Staged.Downloads.Count);Assert.AreEqual(1,e.Provider.AssetStartCount);Assert.AreEqual(1,e.Scheduler.ActiveLoads);Assert.AreEqual(1,e.Scheduler.ActiveDownloads);e.Provider.AssetAt<string>(0).Succeed("a");await a;e.Staged.Downloads[1].Complete(Result<Unit>.Success(default));e.Scheduler.Tick();e.Provider.AssetAt<string>(1).Succeed("b");await b;await e.CloseOwner(owner);await e.Finish();});
        [UnityTest] public IEnumerator CancelDuringDownloadWaitsActualThenSkipsLoad()=>UniTask.ToCoroutine(async()=>{var e=new Env(true);await e.Init();var o=new Scope("d");var wait=e.Assets.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();var close=o.CloseAsync(Cleanup);Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);Assert.AreEqual(1,e.Scheduler.ActiveDownloads);e.Staged.Downloads[0].Complete(Result<Unit>.Success(default));Assert.IsTrue((await close).IsFullyDrained);e.Scheduler.Tick();Assert.AreEqual(0,e.Provider.AssetStartCount);await e.Finish();});
        [UnityTest] public IEnumerator FailedDownloadDoesNotLoadAndQueueContinues()=>UniTask.ToCoroutine(async()=>{var e=new Env(true);await e.Init();var o=new Scope("d");var a=e.Assets.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());var b=e.Assets.Load<string>(Key("b"),o).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();e.Staged.Downloads[0].Complete(Result<Unit>.Failure(Failed));Assert.IsFalse((await a).IsSuccess);e.Scheduler.Tick();Assert.AreEqual(2,e.Staged.Downloads.Count);e.Staged.Downloads[1].Complete(Result<Unit>.Success(default));e.Scheduler.Tick();e.Provider.AssetAt<string>(0).Succeed("b");await b;var close=o.CloseAsync(Cleanup);e.Release();await close;await e.Finish();});
        [UnityTest] public IEnumerator QueuedDeadlineExpiresBeforeProviderAdmission()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();var o=new Scope("timeout");var wait=e.Assets.Load<string>(Key(),o).Value.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)));await UniTask.Delay(15,ignoreTimeScale:true);e.Scheduler.Tick();Assert.AreEqual(ErrorKind.Timeout,(await wait).Error.Kind);Assert.AreEqual(0,e.Provider.AssetStartCount);await o.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator CriticalSharedWaiterPromotesExistingQueuedEntry()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();var o=new Scope("priority");var low=e.Assets.Load<string>(Key(),o,ResourcePriority.Prefetch).Value.WaitAsync(OperationContext.Unlimited());var normal=e.Assets.Load<string>(Key("b"),o).Value.WaitAsync(OperationContext.Unlimited());var high=e.Assets.Load<string>(Key(),o,ResourcePriority.Critical).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();e.Provider.AssetAt<string>(0).Succeed("a");Assert.AreEqual("a",(await high).Value.Value);await low;e.Scheduler.Tick();e.Provider.AssetAt<string>(1).Succeed("b");await normal;await e.CloseOwner(o);await e.Finish();});
        [UnityTest] public IEnumerator ReleaseFailureDoesNotConsumeLoadQuota()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();var o=new Scope("release");var a=e.Assets.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();e.Provider.AssetAt<string>(0).Succeed("a");var lease=(await a).Value;var release=lease.ReleaseAsync(Cleanup);e.Provider.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Failure(Failed));Assert.IsFalse((await release).IsSuccess);var b=e.Assets.Load<string>(Key("b"),o).Value.WaitAsync(OperationContext.Unlimited());e.Scheduler.Tick();Assert.AreEqual(2,e.Provider.AssetStartCount);e.Provider.AssetAt<string>(1).Succeed("b");await b;var retry=lease.RetryReleaseAsync(Cleanup);e.Release(0);await retry;var close=o.CloseAsync(Cleanup);e.Release(1);await close;await e.Finish();});
        [UnityTest] public IEnumerator RuntimeHostDrivesAndUnsubscribesScheduler()=>UniTask.ToCoroutine(async()=>{var go=new GameObject("resource-scheduler-host");try{var host=go.AddComponent<RuntimeHost>();var module=new RuntimeHostModule(host);var s=new ResourceWorkScheduler(Budget(),hostModuleId:module.Id);var c=new GameContext(new[]{new ModuleRegistration(module.Id,module.Dependencies,()=>module,typeof(IRuntimeScheduler)),new ModuleRegistration(s.Id,s.Dependencies,()=>s,typeof(IResourceWorkScheduler))},Cleanup);Assert.IsTrue((await c.StartAsync(OperationContext.Unlimited())).IsSuccess);var backend=host.Scheduler;var job=s.ScheduleFrame(()=>Result<Unit>.Success(default)).Value;Assert.IsTrue((await job.Completion).IsSuccess);Assert.IsTrue((await c.CloseAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(0,backend.TickCount);Assert.IsFalse(host.IsRunning);}finally{UnityEngine.Object.DestroyImmediate(go);}});
        [UnityTest] public IEnumerator HundredCanceledQueueCyclesReturnToBaseline()=>UniTask.ToCoroutine(async()=>{var e=new Env();await e.Init();for(var i=0;i<100;i++){var o=new Scope("c"+i);var wait=e.Assets.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());await o.CloseAsync(Cleanup);await wait;Assert.AreEqual(0,e.Scheduler.QueuedLoads);Assert.AreEqual(0,e.Assets.RetainedEntryCount);}Assert.AreEqual(0,e.Provider.AssetStartCount);await e.Finish();});
    }
}
